<script setup lang="ts">const current=ref(0); const cards=[['你','nǐ','você'],['好','hǎo','bom; bem'],['我','wǒ','eu; mim']]; const card=computed(()=>cards[current.value%cards.length]); const reveal=ref(false); const next=async(rating='good')=>{await $fetch('/api/reviews',{method:'POST',body:{card:card.value[0],rating}}); reveal.value=false;current.value++}</script>
<template><section><div class="page-title"><span class="eyebrow">REPETIÇÃO ESPAÇADA</span><h1>Revisar agora</h1><p class="muted">3 cartões aguardam sua atenção · o algoritmo ajusta a próxima revisão.</p></div><div class="card" style="max-width:620px;text-align:center;padding:45px 25px"><span class="eyebrow">CARTÃO {{current+1}} DE 3 · HANZI → SIGNIFICADO</span><div class="hanzi" style="font-size:105px;margin:30px">{{card[0]}}</div><div v-if="reveal"><h2>{{card[2]}}</h2><p class="muted">{{card[1]}}</p><div class="grid" style="grid-template-columns:repeat(4,1fr);margin-top:30px"><button class="button" @click="next">Errei</button><button class="button" @click="next">Difícil</button><button class="button primary" @click="next">Bom</button><button class="button" @click="next">Fácil</button></div></div><button v-else class="button primary" @click="reveal=true">Mostrar resposta</button></div></section></template>
